import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import { toast } from "react-toastify";

const InfluencerApplyForReels = ({ onClose }) => {
  const navigate = useNavigate();
  
  const [formData, setFormData] = useState({
    firstName: '',
    lastName: '',
    email: '',
    mobile: '',
    platforms: [{ platform: '', link: '' }],
    password: '',
    confirmPassword: ''
  });
  
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState(false);
  
  const handleChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value
    });
  };
  
  const validateProfileUrl = (url, platform) => {
    const p = (platform || '').toLowerCase();
    if (p === 'instagram') {
      // Instagram profile URL validation - allow with or without trailing slash
      const instagramRegex = /^https?:\/\/(www\.)?instagram\.com\/[a-zA-Z0-9._]+\/?(\?.*)?$/;
      return instagramRegex.test(url);
    } else if (p === 'youtube') {
      // YouTube profile URL validation - handle various formats including with query parameters
      const youtubeRegex = /^https?:\/\/(www\.)?youtube\.com\/( @[a-zA-Z0-9._-]+|channel\/[a-zA-Z0-9._-]+|user\/[a-zA-Z0-9._-]+)\/?(\?.*)?$/;
      return youtubeRegex.test(url);
    }
    // For other platforms, allow any URL
    return true;
  };

  const addPlatformEntry = () => {
    setFormData(prev => ({
      ...prev,
      platforms: [...prev.platforms, { platform: '', link: '' }]
    }));
  };

  const removePlatformEntry = (index) => {
    setFormData(prev => ({
      ...prev,
      platforms: prev.platforms.filter((_, i) => i !== index)
    }));
  };

  const handlePlatformEntryChange = (index, field, value) => {
    setFormData(prev => ({
      ...prev,
      platforms: prev.platforms.map((entry, i) => i === index ? { ...entry, [field]: value } : entry)
    }));
  };
  
  const handleSubmit = async (e) => {
    e.preventDefault();
    
    // Validate form
    if (!formData.firstName) {
      setError('First name is required');
      return;
    }
    
    if (!formData.lastName) {
      setError('Last name is required');
      return;
    }
    
    if (!formData.email) {
      setError('Email is required');
      return;
    }
    
    if (!formData.mobile) {
      setError('Mobile number is required');
      return;
    }
    
    if (!formData.platforms || formData.platforms.length === 0) {
      setError('Please add at least one social media platform');
      return;
    }
    
    for (let i = 0; i < formData.platforms.length; i++) {
      const entry = formData.platforms[i];
      if (!entry.platform) {
        setError('Please select a platform for entry ' + (i + 1));
        return;
      }
      if (!entry.link) {
        setError('Please enter a profile URL for entry ' + (i + 1));
        return;
      }
      if (!validateProfileUrl(entry.link, entry.platform)) {
        if ((entry.platform || '').toLowerCase() === 'instagram') {
          setError('Entry ' + (i + 1) + ': valid Instagram URL required (e.g., https://instagram.com/username)');
        } else if ((entry.platform || '').toLowerCase() === 'youtube') {
          setError('Entry ' + (i + 1) + ': valid YouTube URL required (e.g., https://youtube.com/@username or channel)');
        } else {
          setError('Entry ' + (i + 1) + ': please enter a valid profile URL');
        }
        return;
      }
    }
    
    if (!formData.password) {
      setError('Password is required');
      return;
    }
    
    const strongPwd = /^(?=.*[A-Z])(?=.*\d)(?=.*[^A-Za-z0-9]).{8,}$/;
    if (!strongPwd.test(formData.password)) {
      setError('Password must be 8+ chars with uppercase, number, and special character');
      return;
    }
    
    if (formData.password !== formData.confirmPassword) {
      setError('Passwords do not match');
      return;
    }
    
    // Validate profile URL based on platform
    if (!validateProfileUrl(formData.profileUrl, formData.platform)) {
      if (formData.platform === 'instagram') {
        setError('Please enter a valid Instagram profile URL (e.g., https://instagram.com/username)');
      } else if (formData.platform === 'youtube') {
        setError('Please enter a valid YouTube profile URL (e.g., https://youtube.com/@username or https://youtube.com/channel/channel_id)');
      } else {
        setError('Please enter a valid profile URL');
      }
      return;
    }
    
    // Validate mobile number format (basic validation)
    const mobileRegex = /^[0-9]{10,12}$/;
    if (!mobileRegex.test(formData.mobile)) {
      setError('Please enter a valid mobile number (10-12 digits)');
      return;
    }
    
    setLoading(true);
    setError('');
    
    try {
      // Submit form data to backend
      const response = await fetch('/Studio/influencer/apply-for-reels', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          firstName: formData.firstName,
          lastName: formData.lastName,
          email: formData.email,
          mobile: formData.mobile,
          platform: formData.platforms[0]?.platform || '',
          profileUrl: formData.platforms[0]?.link || '',
          platforms: formData.platforms.map(p => ({ platform: p.platform, link: p.link })),
          password: formData.password
        }),
      });
      
      const result = await response.json();
      
      if (response.ok && result.success) {
        setSuccess(true);
        toast.success("Application submitted successfully! You can now login.");
        
        // Close the modal and show login
        setTimeout(() => {
          if (onClose) {
            onClose();
            // Open the login modal
            window.dispatchEvent(new CustomEvent('openLoginModal', { detail: 'influencer-login' }));
          } else {
            navigate("/studio?message=pending_approval");
          }
        }, 2000);
      } else {
        setError(result.message || 'Application failed. Please try again.');
      }
    } catch (err) {
      console.error('Application error:', err);
      setError('Network error. Please try again.');
    } finally {
      setLoading(false);
    }
  };
  
  return (
    <div className="container-fluid">
      <div className="row justify-content-center">
        <div className="col-12">
          {error && (
            <div className="alert alert-danger alert-dismissible fade show" role="alert">
              {error}
              <button 
                type="button" 
                className="btn-close" 
                data-bs-dismiss="alert" 
                aria-label="Close"
                onClick={() => setError("")}
              ></button>
            </div>
          )}
          
          {success && (
            <div className="alert alert-success alert-dismissible fade show" role="alert">
              Application successful! Redirecting to login page...
              <button 
                type="button" 
                className="btn-close" 
                data-bs-dismiss="alert" 
                aria-label="Close"
                onClick={() => setSuccess(false)}
              ></button>
            </div>
          )}
          
          <form onSubmit={handleSubmit} className="mt-3">
            <div className="mb-3">
              <label htmlFor="firstName" className="form-label">
                <i className="fas fa-user me-2"></i>First Name *
              </label>
              <input
                type="text"
                className="form-control form-control-lg rounded"
                id="firstName"
                name="firstName"
                value={formData.firstName}
                onChange={handleChange}
                required
                placeholder="Enter your first name"
              />
            </div>
            
            <div className="mb-3">
              <label htmlFor="lastName" className="form-label">
                <i className="fas fa-user me-2"></i>Last Name *
              </label>
              <input
                type="text"
                className="form-control form-control-lg rounded"
                id="lastName"
                name="lastName"
                value={formData.lastName}
                onChange={handleChange}
                required
                placeholder="Enter your last name"
              />
            </div>
            
            <div className="mb-3">
              <label htmlFor="email" className="form-label">
                <i className="fas fa-envelope me-2"></i>Email Address *
              </label>
              <input
                type="email"
                className="form-control form-control-lg rounded"
                id="email"
                name="email"
                value={formData.email}
                onChange={handleChange}
                required
                placeholder="Enter your email"
              />
            </div>
            
            <div className="mb-3">
              <label htmlFor="mobile" className="form-label">
                <i className="fas fa-mobile-alt me-2"></i>Mobile Number *
              </label>
              <input
                type="tel"
                className="form-control form-control-lg rounded"
                id="mobile"
                name="mobile"
                value={formData.mobile}
                onChange={handleChange}
                required
                placeholder="Enter your mobile number"
              />
            </div>
            
            <div className="mb-3">
              <label htmlFor="platform" className="form-label">
                <i className="fas fa-hashtag me-2"></i>Social Media Platform *
              </label>
              <select
                className="form-select form-select-lg rounded"
                id="platform"
                name="platform"
                value={formData.platform}
                onChange={handleChange}
                required
              >
                <option value="">Select a platform</option>
                <option value="youtube">YouTube</option>
                <option value="instagram">Instagram</option>
                <option value="tiktok">TikTok</option>
                <option value="twitter">Twitter</option>
                <option value="other">Other</option>
              </select>
            </div>
            
            <div className="mb-3">
              <label htmlFor="profileUrl" className="form-label">
                <i className="fas fa-link me-2"></i>Profile URL *
              </label>
              <input
                type="text"
                className="form-control form-control-lg rounded"
                id="profileUrl"
                name="profileUrl"
                value={formData.profileUrl}
                onChange={handleChange}
                required
                placeholder="Enter your profile URL"
              />
              {formData.platform === 'instagram' && (
                <div className="form-text">Example: https://instagram.com/username</div>
              )}
              {formData.platform === 'youtube' && (
                <div className="form-text">Example: https://youtube.com/@username or https://youtube.com/channel/channel_id</div>
              )}
            </div>
            
            <div className="mb-3">
              <label htmlFor="password" className="form-label">
                <i className="fas fa-lock me-2"></i>Password *
              </label>
              <input
                type="password"
                className="form-control form-control-lg rounded"
                id="password"
                name="password"
                value={formData.password}
                onChange={handleChange}
                required
                placeholder="Enter your password"
              />
              <div className="form-text">Use 8+ chars, uppercase, number, and special character</div>
            </div>

            <div className="mb-3">
              <label className="form-label">
                <i className="fas fa-share-nodes me-2"></i>Social Media Platforms *
              </label>
              {formData.platforms.map((entry, index) => (
                <div className="row g-2 align-items-end mb-2" key={index}>
                  <div className="col-md-4">
                    <select
                      className="form-select"
                      value={entry.platform}
                      onChange={(e) => handlePlatformEntryChange(index, 'platform', e.target.value)}
                      required
                      disabled={loading}
                    >
                      <option value="">Select Platform</option>
                      <option value="Instagram">Instagram</option>
                      <option value="YouTube">YouTube</option>
                      <option value="TikTok">TikTok</option>
                      <option value="Facebook">Facebook</option>
                      <option value="Twitter">Twitter</option>
                      <option value="Other">Other</option>
                    </select>
                  </div>
                  <div className="col-md-6">
                    <input
                      type="url"
                      className="form-control"
                      placeholder="Enter profile URL"
                      value={entry.link}
                      onChange={(e) => handlePlatformEntryChange(index, 'link', e.target.value)}
                      required
                      disabled={loading}
                    />
                    {entry.platform && (entry.platform.toLowerCase() === 'instagram') && (
                      <div className="form-text">Example: https://instagram.com/username</div>
                    )}
                    {entry.platform && (entry.platform.toLowerCase() === 'youtube') && (
                      <div className="form-text">Example: https://youtube.com/@username or channel URL</div>
                    )}
                  </div>
                  <div className="col-md-2 d-flex gap-2">
                    {formData.platforms.length > 1 && (
                      <button type="button" className="btn btn-outline-danger w-100" onClick={() => removePlatformEntry(index)} disabled={loading}>
                        Remove
                      </button>
                    )}
                  </div>
                </div>
              ))}
              <button type="button" className="btn btn-outline-primary" onClick={addPlatformEntry} disabled={loading}>
                Add Another Platform
              </button>
            </div>
            
            <div className="mb-3">
              <label htmlFor="confirmPassword" className="form-label">
                <i className="fas fa-lock me-2"></i>Confirm Password *
              </label>
              <input
                type="password"
                className="form-control form-control-lg rounded"
                id="confirmPassword"
                name="confirmPassword"
                value={formData.confirmPassword}
                onChange={handleChange}
                required
                placeholder="Confirm your password"
              />
            </div>
            
            <div className="d-flex justify-content-between">
              <button
                type="button"
                className="btn btn-outline-secondary"
                onClick={onClose}
                disabled={loading}
              >
                Cancel
              </button>
              <button
                className="btn btn-primary d-flex align-items-center justify-content-center gap-1 fw-medium"
                type="submit"
                disabled={loading}
              >
                {loading ? (
                  <>
                    <span className="spinner-border spinner-border-sm me-2" role="status" aria-hidden="true"></span>
                    Submitting...
                  </>
                ) : (
                  <>
                    <i className="fas fa-paper-plane me-2"></i>Submit Application
                  </>
                )}
              </button>
            </div>
          </form>
        </div>
      </div>
    </div>
  );
};

export default InfluencerApplyForReels;
